CONSTANT
    IDLE_STATE : INT := 0;
    EVALUATE_STATE : INT := 1;
    MOVING_STATE : INT := 2;
    WAIT_PROCESS_STATE : INT := 3;
    DONE_STATE : INT := 4;
END_CONSTANT

