FUNCTION_BLOCK FlexibleProcessingControl
VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL;
    conveyorRight : BOOL;
END_VAR
VAR
    state : INT := 0;
    currentStep : USINT := 0;
    currentStation : USINT := 0;
    targetStation : USINT := 0;
    arrived : BOOL := FALSE;
    processingDone : BOOL := FALSE;
    startPressed : BOOL := FALSE;
    startPrev : BOOL := FALSE;
    station2CompletePrev : BOOL := FALSE;
    station3CompletePrev : BOOL := FALSE;
    station4CompletePrev : BOOL := FALSE;
END_VAR

// Constants for readability
CONSTANT
    IDLE_STATE : INT := 0;
    EVALUATE_STATE : INT := 1;
    MOVING_STATE : INT := 2;
    WAIT_PROCESS_STATE : INT := 3;
    DONE_STATE : INT := 4;
END_CONSTANT

// Edge detection for start button
startPressed := station1Start AND NOT startPrev;
startPrev := station1Start;

// Main state machine
CASE state OF
    IDLE_STATE:
        // Reset outputs
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        arrived := FALSE;
        processingDone := FALSE;
        // Wait for start condition: raw material detected and start pressed
        IF sensor1 AND startPressed THEN
            currentStep := 1;
            currentStation := 1;
            state := EVALUATE_STATE;
        END_IF

    EVALUATE_STATE:
