                state := WAIT_PROCESS_STATE;
            END_IF
        ELSE
            // Need to move
            IF targetStation > currentStation THEN
                conveyorRight := TRUE;
                conveyorLeft := FALSE;
            ELSE
                conveyorRight := FALSE;
                conveyorLeft := TRUE;
            END_IF
            state := MOVING_STATE;
        END_IF

    MOVING_STATE:
        // Check arrival at target station using sensors
        arrived := FALSE;
        CASE targetStation OF
            2: IF sensor2 THEN arrived := TRUE; END_IF
            3: IF sensor3 THEN arrived := TRUE; END_IF
            4: IF sensor4 THEN arrived := TRUE; END_IF
            5: IF sensor5 THEN arrived := TRUE; END_IF
        END_CASE

        IF arrived THEN
            // Stop conveyor
            conveyorLeft := FALSE;
            conveyorRight := FALSE;
            currentStation := targetStation;
            arrived := FALSE;

            // After arrival, decide next state
            IF targetStation = 5 THEN
                state := DONE_STATE;
            ELSE
                state := WAIT_PROCESS_STATE;
            END_IF
        END_IF

    WAIT_PROCESS_STATE:
