        processingDone := FALSE;
        // Detect rising edge of appropriate completion signal
        CASE currentStation OF
            2: IF station2Complete AND NOT station2CompletePrev THEN processingDone := TRUE; END_IF
            3: IF station3Complete AND NOT station3CompletePrev THEN processingDone := TRUE; END_IF
            4: IF station4Complete AND NOT station4CompletePrev THEN processingDone := TRUE; END_IF
        END_CASE

        // Update prev signals
        station2CompletePrev := station2Complete;
        station3CompletePrev := station3Complete;
        station4CompletePrev := station4Complete;

        IF processingDone THEN
            processingDone := FALSE;
            // Increment step
            currentStep := currentStep + 1;
            // Check if all steps completed
            IF currentStep > processLength THEN
                state := DONE_STATE;
            ELSE
                state := EVALUATE_STATE;
